"use client";

import * as React from "react";
import {
  PolarAngleAxis,
  PolarGrid,
  PolarRadiusAxis,
  Radar,
  RadarChart as RechartsRadarChart,
  ResponsiveContainer,
  Tooltip,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  type ChartDatum,
  ChartFrame,
  ChartGlowFilter,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  type ChartSeries,
  ChartTooltipContent,
  HOVER_TRANSITION,
  axisTick,
  markOpacity,
  resolveSeries,
  useChartId,
  useChartMotion,
} from "@/components/moneytrees/charts/chart-kit";

export type RadarFillVariant = "filled" | "lines";
export type RadarGridType = "polygon" | "circle";

export interface SpectrumRadarChartProps {
  className?: string;
  data: ChartDatum[];
  xKey: string;
  series: ChartSeries[];
  variant?: RadarFillVariant;
  gridType?: RadarGridType;
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  height?: number;
  formatValue?: (value: number) => string;
}

export function RadarChart({
  className,
  data,
  xKey,
  series,
  variant = "filled",
  gridType = "polygon",
  glowing = false,
  isLoading = false,
  showLegend = true,
  height,
  formatValue,
}: SpectrumRadarChartProps) {
  const id = useChartId("radar");
  const { isAnimationActive, animationDuration } = useChartMotion();
  const [activeKey, setActiveKey] = React.useState<string | null>(null);
  const rings = resolveSeries(series);
  const glowId = `${id}-glow`;
  const filled = variant === "filled";

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend && rings.length > 1 ? <ChartLegend items={rings} /> : null}
      {isLoading ? (
        <ChartLoadingBars count={8} />
      ) : (
        <ChartPlotSurface>
          <ResponsiveContainer width="100%" height="100%">
            <RechartsRadarChart
              data={data}
              cx="50%"
              cy="50%"
              outerRadius="72%"
              onMouseLeave={() => setActiveKey(null)}
            >
              <defs>{glowing ? <ChartGlowFilter id={glowId} /> : null}</defs>
              <PolarGrid gridType={gridType} stroke="currentColor" strokeOpacity={0.18} />
              <PolarAngleAxis dataKey={xKey} tick={axisTick} />
              <PolarRadiusAxis tick={false} axisLine={false} />
              <Tooltip content={<ChartTooltipContent formatValue={formatValue} />} />
              {rings.map((s, i) => (
                <Radar
                  key={s.key}
                  dataKey={s.key}
                  name={s.label}
                  stroke={s.color}
                  fill={s.color}
                  fillOpacity={filled ? (i === 0 ? 0.22 : 0.16) : 0}
                  strokeWidth={2}
                  isAnimationActive={isAnimationActive}
                  animationDuration={animationDuration}
                  animationEasing="ease-out"
                  filter={glowing && i === 0 ? `url(#${glowId})` : undefined}
                  style={{
                    opacity: markOpacity(activeKey, s.key),
                    transition: HOVER_TRANSITION,
                    cursor: "pointer",
                  }}
                  onMouseEnter={() => setActiveKey(s.key)}
                />
              ))}
            </RechartsRadarChart>
          </ResponsiveContainer>
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}
